def choose_move(observation):
    x = 0
    y = 0
    if isinstance(observation, dict):
        pos = observation.get("self_position", observation.get("position", {}))
        x = pos.get("x", 0)
        y = pos.get("y", 0)

    grid_w = observation.get("grid_width", observation.get("gridWidth", 0)) or 0
    grid_h = observation.get("grid_height", observation.get("gridHeight", 0)) or 0

    obstacles = set()
    obs = observation.get("obstacles", [])
    for o in obs:
        ox = o.get("x", 0)
        oy = o.get("y", 0)
        obstacles.add((ox, oy))

    res = observation.get("resources", [])
    best_r = None
    for r in res:
        rx = r.get("x", 0)
        ry = r.get("y", 0)
        if best_r is None:
            best_r = (rx, ry)
        else:
            if (rx - x) * (rx - x) + (ry - y) * (ry - y) < (best_r[0] - x) * (best_r[0] - x) + (best_r[1] - y) * (best_r[1] - y):
                best_r = (rx, ry)

    def ok(px, py):
        if grid_w and grid_h:
            if px < 0 or py < 0 or px >= grid_w or py >= grid_h:
                return False
        return (px, py) not in obstacles

    moves = [(0,-1),(-1,0),(1,0),(0,1),(0,0)]
    target = best_r if best_r is not None else (x, y)

    best_score = None
    best_dir = (0,0)
    for dx, dy in moves:
        nx, ny = x + dx, y + dy
        if not ok(nx, ny):
            continue
        dist = (target[0]-nx)*(target[0]-nx) + (target[1]-ny)*(target[1]-ny)
        s = -dist
        if best_score is None or s > best_score:
            best_score = s
            best_dir = (dx, dy)

    if best_score is None:
        return [0, 0]
    return [best_dir[0], best_dir[1]]
